<script setup lang="ts">
import { Wallet } from '@element-plus/icons-vue'
import type { AdjustmentDraft } from '@/types/adjustment'
defineProps<{ draft: AdjustmentDraft; descriptions: string[]; before: number | null; after: number | null; applying: boolean; rejecting: boolean; canApply: boolean; fullSelection: boolean }>()
defineEmits<{ apply: []; reject: []; continue: []; details: [] }>()
</script>
<template><div class="adjustment-preview"><div class="preview-heading"><h3>调整方案</h3><span>{{ draft.status === 'pending' ? '待你确认' : draft.status === 'applied' ? '已应用' : '已丢弃' }}</span></div><ol class="preview-operations"><li v-for="(description, index) in descriptions" :key="index"><span class="operation-number">{{ index + 1 }}</span><div><strong>{{ description }}</strong><p v-if="draft.operations[index]?.note && draft.operations[index]?.note !== description">{{ draft.operations[index]?.note }}</p></div></li></ol><p v-if="!descriptions.length" class="preview-empty">没有可执行的改动，试试补充具体地点和日期。</p><div class="budget-impact"><span class="budget-impact-icon"><el-icon><Wallet /></el-icon></span><div><div class="budget-impact-heading"><strong>预算影响</strong><span v-if="before !== null && after !== null && fullSelection" :class="after <= before ? 'budget-saved' : 'budget-increased'">{{ after <= before ? '预计节省' : '预计增加' }} ¥{{ Math.abs(after - before).toLocaleString('zh-CN') }}</span></div><p v-if="after !== null">完整方案约 ¥{{ after.toLocaleString('zh-CN') }}<span v-if="before !== null">（调整前 ¥{{ before.toLocaleString('zh-CN') }}）</span></p><p v-else>暂未返回预算估算</p><small v-if="!fullSelection">部分选中，实际预算以应用后重新计算为准。</small></div></div><p v-for="(conflict, i) in draft.conflicts" :key="i" class="preview-conflict">{{ conflict.message }}</p><button class="preview-details" @click="$emit('details')">查看完整草案与费用明细</button></div><div v-if="draft.status === 'pending'" class="preview-actions"><el-button type="primary" :loading="applying" :disabled="!canApply || rejecting" @click="$emit('apply')">应用调整</el-button><el-button :disabled="applying || rejecting" @click="$emit('continue')">继续对话</el-button><button class="reject-draft" :disabled="applying || rejecting" @click="$emit('reject')">{{ rejecting ? '正在丢弃…' : '丢弃草案' }}</button></div></template>
